package app.runsolo.core.trail

import app.runsolo.core.json.Json
import app.runsolo.core.route.RouteFollower
import app.runsolo.core.testio.File
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertNull
import kotlin.test.assertTrue

/**
 * Dart/Kotlin parity for [TrailGhost]: the vectors in `packages/run_engine/test/fixtures/trail_ghost/vectors.json`
 * (generated by the Dart engine's `TrailGhostTracker`, never edited) are replayed fix by fix, and every field of every
 * state must equal the Dart one (position to 0.5 m, times to 1 ms), the turnaround events at the same instants. The
 * Dart side replays the same file (trail_ghost_parity_test.dart).
 */
class TrailGhostParityTest {
    private val file = File("../../packages/run_engine/test/fixtures/trail_ghost/vectors.json")

    private fun num(v: Any?): Double? = (v as Number?)?.toDouble()

    @Test
    fun `every vector state equals the Dart tracker's`() {
        assertTrue(file.exists(), "missing ${file.path}")
        @Suppress("UNCHECKED_CAST")
        val vectors = Json.parseObject(file.readText())["vectors"] as List<Map<String, Any?>>
        assertTrue(vectors.size >= 8)
        var matched = 0
        var never = 0
        var turns = 0
        for (v in vectors) {
            val name = v["name"] as String
            @Suppress("UNCHECKED_CAST")
            val trails = (v["trails"] as List<Map<String, Any?>>).map { TrailRef.fromJson(it) }
            @Suppress("UNCHECKED_CAST")
            val points = v["points"] as List<List<Any?>>
            @Suppress("UNCHECKED_CAST")
            val states = v["states"] as List<List<Any?>>
            assertEquals(points.size, states.size, name)
            val g = TrailGhost(trails)
            val events = ArrayList<Long>()
            var any = false
            for (i in points.indices) {
                val p = points[i]
                for (e in g.offer(
                    t = (p[0] as Number).toLong(),
                    lat = num(p[1])!!,
                    lon = num(p[2])!!,
                    accuracyM = num(p[3])!!,
                    activeMs = (p[4] as Number).toLong(),
                    runDistM = num(p[5])!!,
                )) {
                    events.add((e as RouteFollower.Event.RouteEnd).t)
                }
                val want = states[i]
                val s = g.state
                val at = "$name #$i"
                if (want[0] == null) {
                    assertNull(s, at)
                    continue
                }
                any = true
                assertNotNull(s, at)
                assertEquals(want[0] as String, s.trailId, "$at trail")
                assertEquals(num(want[1])!!, s.alongM, 0.5, "$at along")
                assertEquals(want[2] as Boolean, s.off, "$at off")
                assertEquals((want[3] as Number?)?.toLong(), s.aheadBestMs, "$at best")
                assertEquals((want[4] as Number?)?.toLong(), s.aheadLastMs, "$at last")
                assertEquals(want[5] as Boolean, s.turnCue, "$at cue")
                assertEquals(num(want[6]), s.toTurnM, "$at toTurn")
            }
            @Suppress("UNCHECKED_CAST")
            assertEquals((v["turnEvents"] as List<Number>).map { it.toLong() }, events, "$name turn events")
            if (any) matched++ else never++
            turns += events.size
        }
        assertTrue(matched >= 6)
        assertTrue(never >= 3)
        assertTrue(turns >= 1)
    }
}
